python - <<'PY'
from semver import VersionInfo

for v in (VersionInfo(1), VersionInfo.parse('1.2.3-rc.1+build.2')):
    parts = v.to_tuple()
    expected = dict(zip(('major', 'minor', 'patch', 'prerelease', 'build'), parts))
    assert isinstance(v.to_dict(), dict)
    assert v.to_dict() == expected
    result = v.to_dict()
    result['major'] = 99
    assert v.major == 1
    for i in range(-5, 5):
        assert v[i] == parts[i]
    for start in (None, -10, -3, 0, 2, 5, 10):
        for stop in (None, -10, -1, 0, 3, 5, 10):
            for step in (None, -2, -1, 1, 2):
                s = slice(start, stop, step)
                assert v[s] == parts[s]
    for index, exception in ((5, IndexError), (-6, IndexError), ('major', TypeError), (1.0, TypeError), (slice(None, None, 0), ValueError)):
        try:
            v[index]
        except exception:
            pass
        else:
            raise AssertionError('Expected %s for %r' % (exception, index))
print('Accessor and sequence edge-case checks passed')
PY
